import { DetectedMetadata, InfinityItem } from '@/types';
import { ProviderAdapter } from './types';

export class NotionAdapter implements ProviderAdapter {
  id = 'notion' as const;
  name = 'Notion';

  canHandle(urlString: string): boolean {
    try {
      const url = new URL(urlString);
      const host = url.hostname.toLowerCase();
      if (
        host === 'notion.so' ||
        host.endsWith('.notion.so') ||
        host === 'notion.site' ||
        host.endsWith('.notion.site')
      ) {
        return true;
      }
      // AWS S3 signed URLs generated by Notion for uploaded files
      if (
        (host.includes('notion') && host.includes('amazonaws.com')) ||
        host === 'file.notion.so' ||
        host === 'prod-files-secure.s3.us-west-2.amazonaws.com'
      ) {
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  extractPageOrBlockId(urlString: string): string | null {
    try {
      const url = new URL(urlString);
      // Clean query and hash
      const pathname = url.pathname;
      const match = pathname.match(/[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
      return match ? match[0] : null;
    } catch {
      return null;
    }
  }

  async detect(urlString: string): Promise<DetectedMetadata> {
    const id = this.extractPageOrBlockId(urlString);
    let title = 'Recurso de Notion';
    try {
      const url = new URL(urlString);
      const last = url.pathname.split('/').filter(Boolean).pop();
      if (last) {
        title = decodeURIComponent(last.replace(/-/g, ' '));
      }
    } catch {
      // ignore
    }

    return {
      name: title,
      provider: 'notion',
      category: 'documents',
      metadata: {
        notionId: id || undefined,
        originalUrl: urlString
      }
    };
  }

  getDirectUrl(item: InfinityItem): string {
    // If it's a Notion hosted file with signed URL, we route through our secure refresh proxy
    if (item.metadata?.notionBlockId || item.metadata?.notionPageId) {
      return `/api/notion/resolve?itemId=${encodeURIComponent(item.id)}`;
    }
    return item.url;
  }
}
